function checkRedirectUri(uri: string): void {
  let u: URL;
  try { u = new URL(uri); } catch { throw new Error(`${uri} is not an absolute URL`); }
  if (u.hash || uri.includes("#")) throw new Error(`${uri} must not contain a fragment`);
  if (u.protocol !== "https:" && u.protocol !== "http:") throw new Error(`${uri} must be http(s)`);
  if (u.protocol === "http:" && !["127.0.0.1", "[::1]", "localhost"].includes(u.hostname)) {
    throw new Error(`http ${uri} is only allowed for loopback hosts`);
  }
}
