import { createHash, randomBytes } from "node:crypto";
const sha = (s: string) => createHash("sha256").update(s).digest("base64url");
const families = new Map<string, { revoked: boolean }>();
const tokens = new Map<string, { familyId: string; used: boolean; expiresAt: number }>();

function issue(familyId: string, now: number): string {
  const raw = randomBytes(32).toString("base64url");
  tokens.set(sha(raw), { familyId, used: false, expiresAt: now + 14 * 86400_000 });
  return raw;
}
function rotate(raw: string, now: number): string | "invalid" | "revoked" | "expired" | "reuse" {
  const t = tokens.get(sha(raw));
  if (!t) return "invalid";
  const f = families.get(t.familyId);
  if (!f || f.revoked) return "revoked";
  if (now >= t.expiresAt) return "expired";
  if (t.used) { f.revoked = true; return "reuse"; }
  t.used = true;
  return issue(t.familyId, now);
}

