type K = { kid: string; activatedAt: number | null; retiredAt: number | null };
function rotate(keys: K[], now: number, retainMs: number, newKey: () => K, save: (k: K[]) => void): K[] {
  let promoted = false;
  const after = keys.map((k) => {
    if (k.activatedAt !== null && k.retiredAt === null) return { ...k, retiredAt: now };
    if (k.activatedAt === null && !promoted) { promoted = true; return { ...k, activatedAt: now }; }
    return k;
  });
  if (!promoted) after.push({ ...newKey(), activatedAt: now });
  after.push(newKey());
  const kept = after.filter((k) => !(k.retiredAt !== null && now >= k.retiredAt + retainMs));
  save(kept); // throws -> caller keeps the old array
  return kept;
}

